import json,os,subprocess,sys
sys.path[:0]=['/home/kali/OmnisAI/cli/src','/home/kali/OmnisAI/cli/tests']
from omnis_cli.development import mounts
from omnis_cli.lifecycle import StartError
from test_start_attestation import ProductAttestationTest
from unittest.mock import Mock
import importlib
start=importlib.import_module('omnis_cli.start')
ce={'PATH':'/usr/bin:/bin','HOME':'/nonexistent','DOCKER_HOST':'unix:///nonexistent.sock'}
print(subprocess.run(['docker','compose','version'],env=ce,capture_output=True,text=True,timeout=10).stdout.strip())
for workspace in ('/checkout/plain','/checkout/${HOME}/"quoted"'):
 f=ProductAttestationTest(); f.setUp()
 try:
  r=f.runtime; valid=f.config(); r.receipt.profile='t1-provider-settings'; r.development_workspace=workspace
  for role in ('api','supervisor'):
   if role=='supervisor':
    valid['services'][role]['environment'].update(OMNIS_VAULT_DIR='/vault',OMNIS_VAULT_KEY_DIR='/vault-key',OMNIS_MODEL_EGRESS_DIR='/vault')
    valid['services'][role]['volumes'].extend({'type':'bind','source':str(f.root/name),'target':'/'+name} for name in ('vault','vault-key'))
   expected=mounts(workspace,role)
   payload={'services':{role:{'image':'test:inert','volumes':expected}}}
   p=subprocess.run(['docker','compose','--project-name','r2-readonly','--project-directory','/home/kali/OmnisAI','--env-file','/dev/null','-f','-','config','--format','json'],input=json.dumps(payload).replace('$','$$'),text=True,capture_output=True,timeout=10,env=ce)
   assert p.returncode==0,p.stderr
   actual=json.loads(p.stdout)['services'][role]['volumes']
   if role=='api': print('workspace',workspace,'expected',json.dumps(expected[0]),'rendered',json.dumps(actual[0]))
   valid['services'][role]['volumes'].extend(actual)
  r.compose=Mock(return_value=subprocess.CompletedProcess([],0,json.dumps(valid)))
  def probe(label):
   r.compose.return_value=subprocess.CompletedProcess([],0,json.dumps(valid))
   try: start.validate_config(r,f.env)
   except StartError as e: print(label,e.reason,e.code); return False
   print(label,'ACCEPTED'); return True
  assert not probe('REAL_COMPOSE')
  for role in ('api','supervisor'):
   for m in valid['services'][role]['volumes']:
    if m.get('bind')=={'propagation':'rprivate'}: m['bind']['create_host_path']=False
  ok=probe('INSERT_FALSE_ONLY')
  assert ok==('$' not in workspace)
  if not ok:
   for role in ('api','supervisor'):
    for m in valid['services'][role]['volumes']:
     m['source']=m['source'].replace('$$','$')
   assert probe('SYNTHETIC_ORIGINAL_PATH')
  print('product_effect_calls',r.run.call_count)
 finally: f.doCleanups()
